        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)PhotoModeFeature_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)PhotoModeFeature_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.XALG:
                {
                    _XALGLocation = (stream.Position - offset);
                    return (int)PhotoModeFeature_FieldIndex.XALG;
                }
                case RecordTypeInts.FTAG:
                {
                    this.FormTags = BinaryOverlayList.FactoryByArray<String>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        getter: (s, p) => BinaryStringUtility.ProcessWholeToZString(p.MetaData.Constants.Subrecord(s).Content, encoding: p.MetaData.Encodings.NonTranslated),
                        locs: ParseRecordLocations(
                            stream: stream,
                            constants: _package.MetaData.Constants.SubConstants,
                            trigger: RecordTypes.FTAG,
                            skipHeader: false,
                            translationParams: translationParams));
                    return (int)PhotoModeFeature_FieldIndex.FormTags;
                }
                case RecordTypeInts.FULL:
                {
                    _FULLLocation = (stream.Position - offset);
                    return (int)PhotoModeFeature_FieldIndex.FULL;
                }
                case RecordTypeInts.ICON:
                {
                    _ICONLocation = (stream.Position - offset);
                    return (int)PhotoModeFeature_FieldIndex.ICON;
                }
                case RecordTypeInts.FNAM:
                {
                    _FNAMLocation = (stream.Position - offset);
                    return (int)PhotoModeFeature_FieldIndex.FNAM;
                }
                case RecordTypeInts.INAM:
                {
                    _IconLocation = (stream.Position - offset);
                    return (int)PhotoModeFeature_FieldIndex.Icon;
                }
                case RecordTypeInts.KNAM:
                {
                    _KeywordLocation = (stream.Position - offset);
                    return (int)PhotoModeFeature_FieldIndex.Keyword;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    this.Conditions = BinaryOverlayList.FactoryByCountPerItem<IConditionGetter>(
                        stream: stream,
                        package: _package,
                        countLength: 4,
                        trigger: Condition_Registration.TriggerSpecs,
                        countType: RecordTypes.CITC,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ConditionBinaryOverlay.ConditionFactory(new OverlayStream(s, p), p, recConv),
                        skipHeader: false);
                    return (int)PhotoModeFeature_FieldIndex.Conditions;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
